CREATE TABLE sesiones_acceso (id uuid PRIMARY KEY, cuenta_id uuid NOT NULL REFERENCES cuentas(id), secreto_hash char(64) NOT NULL UNIQUE, creada_en timestamptz NOT NULL, vence_en timestamptz NOT NULL, revocada_en timestamptz);
CREATE TABLE idempotencias (operacion varchar(100) NOT NULL, actor varchar(100) NOT NULL, clave uuid NOT NULL, huella char(64) NOT NULL, actividad_id uuid REFERENCES actividades(id) ON DELETE CASCADE, estado_http integer NOT NULL, resultado jsonb NOT NULL, creada_en timestamptz NOT NULL, vence_en timestamptz NOT NULL, PRIMARY KEY(operacion,actor,clave));
CREATE TABLE contadores_limite (ambito char(64) NOT NULL, ventana bigint NOT NULL, conteo integer NOT NULL CHECK(conteo>0), vence_en timestamptz NOT NULL, PRIMARY KEY(ambito,ventana));
CREATE TABLE auditoria_actividad (id uuid PRIMARY KEY, actividad_id uuid NOT NULL REFERENCES actividades(id) ON DELETE CASCADE, actor_id uuid NOT NULL REFERENCES cuentas(id), accion varchar(100) NOT NULL, instante timestamptz NOT NULL, correlacion uuid NOT NULL, razon varchar(2000), anterior jsonb NOT NULL DEFAULT '{}', nuevo jsonb NOT NULL DEFAULT '{}');
CREATE INDEX auditoria_actividad_instante_idx ON auditoria_actividad(actividad_id,instante,id);
